const payload = $json.body ?? {};
const messages = Array.isArray(payload.messages) ? payload.messages : [];
const events = [];
for (const message of messages) {
  if (!message || message.is_group === true || message.chat_type === 'group') continue;
  const providerMessageId = String(message.id ?? '').trim();
  const rawNumber = String(message.number ?? '').trim();
  if (rawNumber.includes('-')) continue;
  const digits = rawNumber.replace(/\D/g, '');
  const phoneInternational = digits ? `+${digits}` : '';
  const validId = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,179}$/.test(providerMessageId);
  const validPhone = /^\+[1-9]\d{7,14}$/.test(phoneInternational);
  if (!validId || !validPhone) continue;
  const direction = message.from_me === true ? 'outbound' : 'inbound';
  if (message.type === 'text') {
    const text = String(message.text ?? '').trim();
    if (!text || text.length > 10000) continue;
    events.push({ providerMessageId, phoneInternational, direction, messageType: 'text', text });
    continue;
  }
  if (message.type === 'link') {
    const link = String(message.link ?? '').trim();
    if (!/^https:\/\/[^\s]{1,1988}$/.test(link)) continue;
    const caption = String(message.text ?? '').trim();
    events.push({ providerMessageId, phoneInternational, direction, messageType: 'link', link, ...(caption && caption.length <= 1000 ? { caption } : {}) });
    continue;
  }
  if (message.type === 'location') {
    const latitude = Number(message.latitude);
    const longitude = Number(message.longitude);
    if (!Number.isFinite(latitude) || latitude < -90 || latitude > 90) continue;
    if (!Number.isFinite(longitude) || longitude < -180 || longitude > 180) continue;
    const address = String(message.address ?? '').trim();
    events.push({ providerMessageId, phoneInternational, direction, messageType: 'location', latitude, longitude, ...(address && address.length <= 300 ? { address } : {}) });
  }
}
return [{ json: { events } }];
